# ── v2 completion (24 Nov 2026): second worked scenario and a sixth taught section ──
def _sec(sid):
    return next(s for s in MODULE["sections"] if s["id"] == sid)

_sec("project")["html"] += """
<div class="tc-scene"><span class="tc-lab">From "improve infection control" to something countable &middot; fictional</span><p>Nurse Kris, three months into the infection prevention portfolio, proposes a capstone project to "improve infection control in the unit." Her preceptor asks her to narrow it until it has one measure, one denominator and one change she can test in six weeks.</p><p>Kris looks at her own audit data. Catheter hub disinfection before connection was observed correctly in 38 of 60 observations last month (63 percent). She writes an aim: "Raise correct hub disinfection at connection from 63 to 90 percent within six weeks, measured by 15 observed connections a week across all shifts." Her first test of change is a laminated step card clipped to each catheter tray on one shift for one week. Her balancing measure is connection time, so the fix does not quietly slow the whole shift.</p><p class="tc-scene-take"><b>What this shows.</b> A good capstone is small enough to finish and honest enough to fail. The run chart, not the intention, is the evidence.</p></div>
"""

_present = {"id": "present", "nav": "Presenting evidence", "tag": "Practice", "h2": "Present evidence, not effort",
 "html": """
<p>The fourth station asks you to present your portfolio. Examiners are not scoring how hard you worked; they are asking whether the work changed anything and whether you can tell the difference between what you did and what it achieved.</p>
<ol class="tc-flow">
<li><b>The problem, with a number</b>What was happening before, with its numerator and denominator (Module 6).</li>
<li><b>What you changed</b>The tests of change, in order, including the ones that did not work.</li>
<li><b>What the data show</b>A run chart with its median and any run-rule signal, and the balancing measure.</li>
<li><b>What you cannot claim</b>Small numbers, a short time frame, other changes happening at the same time.</li>
<li><b>What happens next</b>Who owns the measure after the project, and how often it will be checked.</li>
</ol>
<div class="tc-scene"><span class="tc-lab">"Zero infections" &middot; fictional</span><p>Nurse Carlo opens his presentation with a slide reading "Zero bloodstream infections in March!" The examiner asks how many catheter patient-months the unit had in March. Carlo checks: 11. She asks how many infections the unit usually has. About one every three or four months.</p><p>Carlo revises his claim during the station: "One month with no infection in 11 catheter patient-months is consistent with our usual rate. I can't say yet that the bundle changed it. What I can show is that observed hub disinfection rose from 63 to 88 percent over six weeks, and I'll keep tracking infections per 100 catheter patient-months monthly for a year."</p><p class="tc-scene-take"><b>What this shows.</b> A rare event in a small denominator often reads zero by chance. An honest presenter separates the process measure that clearly moved from the outcome that needs much longer to judge, and scores higher for it.</p></div>
<div class="tc-keyp"><span class="tc-lab">Remember</span>Completing this module records self-study and a simulation result. Facility competency is still observed and signed off in your employer's records.</div>
"""}
MODULE["sections"].insert([s["id"] for s in MODULE["sections"]].index("marking") + 1, _present)
